<div class="section-heading"><div><div class="eyebrow">Barbearia</div><h1>Fila e encaixes</h1><p class="text-secondary mb-0">Atenda clientes sem horário marcado sem perder o controle da agenda.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-primary" href="/barber/commands">Comandas</a><a class="btn btn-primary" href="/appointments">Agenda</a></div></div>
<div class="card mb-4"><div class="card-body"><h2 class="h5">Adicionar à fila</h2><form method="post" action="/barber/queue" class="row g-3"><?=\App\Core\CSRF::field()?><div class="col-md-4"><label class="form-label">Cliente cadastrado</label><select class="form-select" name="customer_id"><option value="">Cliente de balcão</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=htmlspecialchars($c['name'])?><?=!empty($c['phone'])?' · '.htmlspecialchars($c['phone']):''?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Nome (se não cadastrado)</label><input class="form-control" name="customer_name"></div><div class="col-md-2"><label class="form-label">Telefone</label><input class="form-control" name="customer_phone"></div><div class="col-md-3"><label class="form-label">Serviço</label><select class="form-select" name="service_id" required><option value="">Selecione</option><?php foreach($services as $s):?><option value="<?=(int)$s['id']?>"><?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Preferência de profissional</label><select class="form-select" name="preferred_professional_id"><option value="">Primeiro disponível</option><?php foreach($professionals as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Prioridade</label><input class="form-control" type="number" min="-10" max="10" name="priority" value="0"></div><div class="col-md-4"><label class="form-label">Observação</label><input class="form-control" name="notes"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Entrar na fila</button></div></form></div></div>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Ordem</th><th>Cliente</th><th>Serviço</th><th>Preferência</th><th>Espera</th><th>Status</th><th></th></tr></thead><tbody><?php $n=0;foreach($entries as $e):$n++;?><tr><td><strong><?=$n?></strong></td><td><?=htmlspecialchars($e['customer_name'])?><small class="d-block text-secondary"><?=htmlspecialchars($e['customer_phone']??'')?></small></td><td><?=htmlspecialchars($e['service_name'])?></td><td><?=htmlspecialchars($e['assigned_name']??$e['preferred_name']??'Primeiro disponível')?></td><td><?=(int)$e['wait_minutes']?> min</td><td><span class="badge text-bg-<?=in_array($e['status'],['waiting','called'],true)?'warning':($e['status']==='in_service'?'info':($e['status']==='completed'?'success':'secondary'))?>"><?=htmlspecialchars($e['status'])?></span></td><td><div class="d-flex gap-1 flex-wrap"><?php if($e['status']==='waiting'):?><form method="post" action="/barber/queue/<?=(int)$e['id']?>/call"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-warning">Chamar</button></form><?php endif;?><?php if(in_array($e['status'],['waiting','called'],true)):?><form method="post" action="/barber/queue/<?=(int)$e['id']?>/start" class="d-flex gap-1"><?=\App\Core\CSRF::field()?><?php if(!$boundProfessional):?><select class="form-select form-select-sm" name="professional_id" required><option value="">Profissional</option><?php foreach($professionals as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select><?php endif;?><button class="btn btn-sm btn-success">Iniciar</button></form><form method="post" action="/barber/queue/<?=(int)$e['id']?>/cancel"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-danger">Cancelar</button></form><?php endif;?><?php if($e['appointment_id']):?><a class="btn btn-sm btn-outline-primary" href="/appointments">Atendimento #<?=(int)$e['appointment_id']?></a><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$entries):?><tr><td colspan="7" class="empty-state">Fila vazia.</td></tr><?php endif;?></tbody></table></div></div>
